{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Trovafloxacin, a difluorophenyl-containing fluoroquinolone with polar/ionizable groups, had mean absolute oral bioavailability of 87.6% in fasting healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "A population PK model estimated 74.6% oral bioavailability for a difluorobenzyl heterocycle analogue, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Genaconazole, a difluorophenyl triazole sulfone, showed 100% absolute oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "LY3000328, a difluorophenyl piperazine carbamate, had oral bioavailability of at least 48.4–66.5% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "The analogue with a difluorobenzyl amide and fused pyridone core had absolute bioavailability of about 64% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Loxapine, despite high hepatic extraction, had systemic availability of 29% in humans, meeting the F>=20% threshold and supporting high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Dovitinib, a piperazine-containing kinase inhibitor, had oral bioavailability around 75% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lumateperone, a piperazine-containing antipsychotic, had absolute oral bioavailability of about 4.4% in humans due to extensive first-pass metabolism, arguing for low F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High F is better supported: multiple human oral bioavailability measurements in structurally related difluorophenyl/heteroaromatic/amine-containing analogues range from 29% to 100%, all meeting the F>=20% threshold, while the only low-F analogue (lumateperone, 4.4%) has lower similarity and its extensive first-pass metabolism is not clearly shared by the query.",
  "evidence_gaps": [
    "No direct pharmacokinetic data for the exact query molecule.",
    "All evidence analogues have low Morgan similarity (<0.22), limiting transferability.",
    "No metabolic stability or first-pass extraction data for the query; lumateperone's low F is metabolism-driven and may not transfer.",
    "Physicochemical prior suggests low passive permeability, but no direct absorption or transporter data.",
    "One trovafloxacin record (C01) reports 25% RBA, conflicting with multiple absolute F ~88% studies; treated as low-weight outlier."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

